from pathlib import Path
import base64,gzip
data=gzip.decompress(base64.b64decode(""""""))
Path("ios/IGNIDOWake/StreakParity.swift").write_bytes(data)
p=Path("ios/IGNIDOWake/Info.plist")
s=p.read_text().replace('<string>2.5.0</string>','<string>2.6.0</string>',1).replace('<string>150</string>','<string>160</string>',1)
p.write_text(s)
p=Path("ios/project.yml")
s=p.read_text().replace('CFBundleShortVersionString: "2.5.0"','CFBundleShortVersionString: "2.6.0"',1).replace('CFBundleVersion: "150"','CFBundleVersion: "160"',1)
p.write_text(s)
assert 'DragonScaleTexture' in data.decode()
assert 'RealisticDragonBodyShape' in data.decode()
print("iOS 2.6.0 realistic dragon renderer installed")